.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 12px 22px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  line-height: 1.4;
  font-weight: 600;
  text-align: center;
  transition:
    background-color var(--motion-feedback),
    transform var(--motion-press),
    color var(--motion-feedback);
}.ds-button-primary {
  background: var(--primary);
  color: var(--primary-foreground);
}.ds-button-primary:hover {
  background: var(--accent-foreground);
}.ds-button:active:not(:disabled) {
  transform: translateY(1px);
}.ds-button:disabled {
  opacity: 0.45;
}.ds-control:focus-visible{outline:2px solid var(--ring);outline-offset:4px;}.ds-button{font-family:var(--font-manrope),Arial,sans-serif;border:0;} .ds-button-outline,.ds-button-ghost{color:var(--foreground);}

