.ds-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 26px;
  padding: 4px 10px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.045em;
  border-radius: var(--radius-pill);
  background: var(--surface-secondary);
  color: var(--foreground);
}.ds-badge{font-family:var(--font-manrope),Arial,sans-serif;}

.ds-tab {
  min-height: 44px;
  flex-shrink: 0;
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  transition:
    background var(--motion-feedback),
    color var(--motion-feedback);
}.ds-tab:hover {
  background: var(--surface-secondary);
}.ds-tab[aria-pressed="true"] {
  background: var(--foreground);
  color: var(--surface);
}.ds-tab{border:0;font-family:var(--font-manrope),Arial,sans-serif;}.ds-control:focus-visible{outline:2px solid var(--ring);outline-offset:4px;}

.ds-language select {
  width: 70px;
  min-height: 44px;
  padding: 8px 4px;
  background: var(--background);
  color: var(--foreground);
  border: 0;
  border-radius: var(--radius-sm);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}.ds-language select:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}.ds-language{font-family:var(--font-manrope),Arial,sans-serif;}.ds-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);}
